import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const GENERATED_DIR = new URL("../src/generated/", import.meta.url).pathname;
const BARREL_PATH = join(GENERATED_DIR, "types.ts");

const HEADER =
  "// AUTO-GENERATED by scripts/generate-types.ts — do not edit.\n" +
  "// Re-exports every ts-rs generated type and the hand-written shared types.\n";

const TRAILER = 'export type { ExtensionOptions, StatusData } from "../shared-types.js";\n';

/** Render the generated barrel from a list of exported type names. */
export function barrelSource(names: string[]): string {
  const exports = [...names]
    .sort((a, b) => a.localeCompare(b))
    .map((name) => `export type { ${name} } from "./${name}";`)
    .join("\n");

  return `${HEADER}\n${exports}\n\n${TRAILER}`;
}

/** Read the exported type name from a ts-rs module. */
function typeName(file: string): string | null {
  const source = readFileSync(join(GENERATED_DIR, file), "utf8");
  return /^export type (\w+)/m.exec(source)?.[1] ?? null;
}

export function collectTypeNames(): string[] {
  return readdirSync(GENERATED_DIR)
    .filter((file) => file.endsWith(".ts") && file !== "types.ts")
    .map(typeName)
    .filter((name): name is string => name !== null);
}

function main(): void {
  const names = collectTypeNames();
  writeFileSync(BARREL_PATH, barrelSource(names));
  console.info(`wrote ${names.length} type re-exports to ${BARREL_PATH}`);
}

if (import.meta.main) main();
